import math
n = int(input())
l = list(map(int, input().split()))
count = 0
for i in range(n):
	if l[i] == 1:
		count += 1
if count != 0:
	print(n - count)
	exit()
ss = 0
mi = 10 ** 9 + 7
for i in range(n):
	ss = l[i]
	for j in range(i + 1, n):
		ss = math.gcd(l[j], ss)
		if ss == 1:
			mi = min(mi, j - i)
if mi == 10 ** 9 + 7:
	print(-1)
else:
	print(mi + n - 1)
